const out='.verification/owned-phone-final-cleanup-v2-20261024.json';if(existsSync(out))throw Error('RECEIPT_EXISTS_INSPECT_BEFORE_RETRY');const proof=JSON.parse(readFileSync('.verification/samsung-natalia-production-journey-v3-20261024.json')),guard=JSON.parse(readFileSync('.verification/owned-natalia-journeys-cleanup-guard-probe-v2-20261024.json'));const valid=JSON.parse(readFileSync('.verification/owned-natalia-journeys-cleanup-valid-probe-20261024.json'));if(!proof.passed||!guard.passed||!valid.passed)throw Error('NATIVE_PROOF_OR_CLEANUP_GUARD_MISSING');
