const serial='192.168.100.10:45061',forwards=run('adb',['forward','--list']).trim().split('\n').filter(Boolean).map(x=>x.trim().split(/\s+/));if(!forwards.some(x=>x[0]===serial&&x[1]==='tcp:35365'&&x[2]==='localabstract:chrome_devtools_remote'))throw Error('OWN_FORWARD_CHANGED');run('adb',['-s',serial,'forward','--remove','tcp:35365']);const remaining=run('adb',['forward','--list']);if(remaining.split('\n').some(x=>x.includes('tcp:35365')))throw Error('OWN_FORWARD_REMAINS');r.ownedForwardRemoved=true;r.adbPairingAndBrowserPermissionUntouched=true;r.status='owned-data-notifications-tab-and-forward-cleaned';r.finishedAt=new Date().toISOString();r.passed=true;save();console.log({status:r.status,passed:true,otherTabsPreserved:true,historicalCalendarPreserved:true});
